import assert from 'node:assert/strict';
import test from 'node:test';
import { computeDueDate } from '../lib/circulation/due-dates.js';
import { branchById } from '../lib/config/branches.js';

test('a book is due three weeks after it is lent', () => {
  const dueOn = computeDueDate({ checkedOutOn: '2026-11-26', format: 'book', branch: branchById('central') });
  assert.equal(dueOn, '2026-12-17');
});

test('a due date that falls on a closed day moves to the next open day', () => {
  const dueOn = computeDueDate({
    checkedOutOn: '2026-11-22',
    format: 'dvd',
    branch: branchById('riverside'),
  });
  assert.equal(dueOn, '2026-12-01');
});

test('a due date that falls on a holiday of the branch moves to the next open day', () => {
  // 2026-12-04 + 21 days is Friday 2026-12-25, a holiday at central.
  const dueOn = computeDueDate({ checkedOutOn: '2026-12-04', format: 'book', branch: branchById('central') });
  assert.equal(dueOn, '2026-12-26');
});

test('a holiday followed by closed weekdays moves to the first open day after them', () => {
  // Hillcrest is closed on 2026-12-25 (holiday), then on Saturday and Sunday.
  const dueOn = computeDueDate({ checkedOutOn: '2026-12-04', format: 'book', branch: branchById('hillcrest') });
  assert.equal(dueOn, '2026-12-28');
});

test('only the holidays of the branch the item belongs to count', () => {
  // 2026-12-24 is a holiday at riverside but not at central.
  const central = computeDueDate({ checkedOutOn: '2026-12-03', format: 'book', branch: branchById('central') });
  const riverside = computeDueDate({ checkedOutOn: '2026-12-03', format: 'book', branch: branchById('riverside') });
  assert.equal(central, '2026-12-24');
  assert.equal(riverside, '2026-12-26');
});

test('a laptop is due the next day', () => {
  const dueOn = computeDueDate({
    checkedOutOn: '2026-11-26',
    format: 'laptop',
    branch: branchById('hillcrest'),
  });
  assert.equal(dueOn, '2026-11-27');
});

